import{z as i,x as s,o as B,c as A,q as o,j as r,D as e,d as n,s as l,S as p,b as a}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"混同与分离","description":"","frontmatter":{"title":"混同与分离","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/pooling-separating.md","filePath":"econ/pooling-separating.md","lastUpdated":1791413859000}'),d={name:"econ/pooling-separating.md"};function m(C,E,h,u,D,F){const t=s("Mermaid");return B(),A("div",null,[E[2]||(E[2]=o('<h1 id="混同与分离" tabindex="-1">混同与分离 <a class="header-anchor" href="#混同与分离" aria-label="Permalink to &quot;混同与分离&quot;">​</a></h1><div class="epigraph"><p>完美贝叶斯均衡可以是所有类型发同一信号，也可以是各发各的；两类均衡的差别在路径外信念，不在教育是不是生产。</p><footer>—— 据 Spence, QJE, 1973；Mas-Colell, Whinston and Green, Microeconomic Theory, ch. 13</footer></div><p><a href="/econ/spence-signaling">上一课</a>已经用单交叉写出最小成本分离，并说明混同靠怪信念撑住。缺口是把两类 PBE 的构造写全：策略、路径上信念、路径外信念各写什么，精炼删哪一类。本课不重讲「教育可不提高产出」的故事，只把混同与分离当成信念–策略的两套解。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两类型 \\(\\theta\\in\\{L,H\\}\\)，信号 \\(e\\)，接收者后验 \\(\\mu(e)\\)，支付（工资、价格）等于后验期望。PBE：发送者对后验最优，接收者在路径上贝叶斯，路径外信念任意（再加精炼）。分离：\\(\\mathrm{supp}(e_L)\\cap\\mathrm{supp}(e_H)=\\emptyset\\)，路径上 \\(\\mu\\) 退化到真类型。混同：两类选同一 \\(e^p\\)，路径上 \\(\\mu\\) 等于先验。半分离：一类型纯、另一类型混，本课只作边界。</p><p>分离的构造：先定低类型的完全信息最优 \\(e_L\\)（常为 \\(0\\)），再找最低 \\(e_H\\) 使低类型模仿不划算、高类型宁可分离。单交叉保证这段不等式有解。再高的 \\(e_H\\) 也是分离 PBE——路径外把更低的 \\(e\\) 判给低类型即可。混同的构造：选 \\(e^p\\)，工资等于平均产出；对任何 \\(e\\neq e^p\\)，指定 \\(\\mu(e)\\) 使两类都不想偏。常见撑法是 \\(\\mu(e)=0\\)（判给低类型）。直觉标准：若低类型更不愿意发某个 \\(e&#39;\\)，则不该把 \\(e&#39;\\) 判给他，于是许多混同垮、浪费型分离也垮，留下最小成本分离。</p><p><span class="marginnote">术语翻译：路径外信念指「对没发生的事怎么想」。某处信号本来没人发，贝叶斯公式算不出那里的后验，均衡便允许构造者自由指定它——混同均衡的生死全押在这句「自由指定」上，所以它必须写出来，不能省略。</span></p><h3 id="构造先于故事" tabindex="-1">构造先于故事 <a class="header-anchor" href="#构造先于故事" aria-label="Permalink to &quot;构造先于故事&quot;">​</a></h3><p>同一套 \\((e,\\mu)\\) 可以贴在教育、担保、广告上。差别只是成本函数谁更陡。本课不再解释「为什么学校存在」，只写这两类均衡各自需要哪些信念。</p><p><span class="marginnote">MWG 第 13 章把 Spence 收成：分离的激励相容几何 + 混同对路径外信念的依赖。Cho–Kreps 直觉标准、Banks–Sobel 神性、D1 是同一精炼家族；课堂上最小成本分离几乎总是唯一幸存者。</span></p><p>混同不是「没有信息」，而是路径上信息量为零。 分离不是「信息完全」，而是路径上类型被点识别；路径外仍可任意。 精炼改的是允许哪些任意，不是改贝叶斯公式。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：两类型、连续信号、竞争性接收者、PBE。步骤：(1) 写分离候选，检查双方 IC；(2) 写混同候选，补全路径外 \\(\\mu\\)；(3) 用直觉标准删。不要在每一步重算教育的生产函数。</p>',13)),(B(),r(p,null,{default:e(()=>[l(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20PBE%5B%22PBE%EF%BC%9A%E7%AD%96%E7%95%A5%20%2B%20%E4%BF%A1%E5%BF%B5%22%5D%20--%3E%20SEP%5B%22%E5%88%86%E7%A6%BB%EF%BC%9A%E8%B7%AF%E5%BE%84%E4%B8%8A%20%CE%BC%20%E9%80%80%E5%8C%96%22%5D%0A%20%20PBE%20--%3E%20POOL%5B%22%E6%B7%B7%E5%90%8C%EF%BC%9A%E8%B7%AF%E5%BE%84%E4%B8%8A%20%CE%BC%20%3D%20%E5%85%88%E9%AA%8C%22%5D%0A%20%20POOL%20--%3E%20OFF%5B%22%E9%9D%A0%E8%B7%AF%E5%BE%84%E5%A4%96%20%CE%BC%20%E6%8C%A1%E4%BD%8F%E5%81%8F%E7%A6%BB%22%5D%0A%20%20REF%5B%22%E7%9B%B4%E8%A7%89%E6%A0%87%E5%87%86%20%2F%20D1%22%5D%20--%3E%20MIN%5B%22%E5%B8%B8%E5%8F%AA%E7%95%99%E6%9C%80%E5%B0%8F%E6%88%90%E6%9C%AC%E5%88%86%E7%A6%BB%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[n(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[n("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"单交叉给出无差异曲线一次相交，于是存在一段 \\(e\\) 只对高类型划算。分离把这段变成路径。混同把这段藏起来：人人停在 \\(e^p\\)，偏离者被信念惩罚。PBE 过松，正因为惩罚可以任意狠。精炼要求惩罚与「谁更想偏离」一致，混同就失去惩罚工具。这是信念的约束，不是成本函数变了。",-1)),E[5]||(E[5]=a("p",null,"混同的惩罚机器如何运转、精炼如何拆掉它：",-1)),(B(),r(p,null,{default:e(()=>[l(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20PO%5B%22%E6%B7%B7%E5%90%8C%EF%BC%9A%E4%BA%BA%E4%BA%BA%E5%81%9C%E5%9C%A8%20e%5Ep%22%5D%20--%3E%20DEV%5B%22%E6%9F%90%E7%B1%BB%E6%83%B3%E5%81%8F%E7%A6%BB%E5%88%B0%E5%88%AB%E7%9A%84%20e%22%5D%0A%20%20DEV%20--%3E%20OFF%5B%22%E8%B7%AF%E5%BE%84%E5%A4%96%E4%BF%A1%E5%BF%B5%E6%8A%8A%E5%81%8F%E7%A6%BB%E8%80%85%E5%88%A4%E4%B8%BA%E4%BD%8E%E7%B1%BB%E5%9E%8B%22%5D%0A%20%20OFF%20--%3E%20W%5B%22%E5%B7%A5%E8%B5%84%E8%B7%8C%E5%88%B0%E5%B9%B3%E5%9D%87%E4%B9%8B%E4%B8%8B%EF%BC%9A%E5%81%8F%E7%A6%BB%E4%B8%8D%E5%88%92%E7%AE%97%22%5D%0A%20%20W%20--%3E%20B%5B%22%E6%B7%B7%E5%90%8C%E9%9D%A0%E6%80%AA%E4%BF%A1%E5%BF%B5%E6%92%91%E4%BD%8F%22%5D%0A%20%20RE%5B%22%E7%B2%BE%E7%82%BC%E8%BF%BD%E9%97%AE%EF%BC%9A%E8%B0%81%E6%9B%B4%E6%83%B3%E5%81%8F%E7%A6%BB%EF%BC%9F%22%5D%20--%3E%20C%5B%22%E4%BD%8E%E7%B1%BB%E5%9E%8B%E6%9B%B4%E6%80%95%E9%AB%98%20e%EF%BC%9A%E4%B8%8D%E5%BA%94%E5%88%A4%E7%BB%99%E4%BB%96%22%5D%0A%20%20C%20--%3E%20P%5B%22%E6%83%A9%E7%BD%9A%E5%A4%B1%E5%8E%BB%E4%BE%9D%E6%8D%AE%EF%BC%9A%E6%B7%B7%E5%90%8C%E5%9E%AE%22%5D%0A%20%20P%20--%3E%20M%5B%22%E5%B9%B8%E5%AD%98%EF%BC%9A%E6%9C%80%E5%B0%8F%E6%88%90%E6%9C%AC%E5%88%86%E7%A6%BB%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[n(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=o('<p><span class="marginnote">直觉类比：混同像全班交同一份作业，老师对「交别种答案」一律默认按抄袭处理。没人敢交真答案，不是真答案差，而是惩罚规则把所有偏离一律判死；精炼做的事是追问——这道惩罚对「谁更不敢偏离」说得通吗？说不通，混同就散了。</span></p><p>与柠檬对照：柠檬是没有 \\(e\\) 的退化混同，切断靠价格。有 \\(e\\) 之后，混同仍可能，但多了一维用来分离。筛选课把时序反过来，混同/分离改写在菜单上，不是在发送者的 \\(e\\) 上；本课保持知情者先动。分离的工资等于真产出，混同等于平均产出；两者的福利差是信号耗散减去柠檬式错配。精炼留下最小成本分离，等于把耗散压到刚好挡住低类型，再高的分离 PBE 被删。</p><p>只写「存在混同」而不写路径外 \\(\\mu\\)，等于没构造。 分离若声称唯一，必须声明用了哪条精炼，否则更高的 \\(e_H\\) 也是 PBE。</p><p>两类型已经够把时序与信念钉住；连续类型把分离收成微分方程，混同变成区间池，精炼更绕，本课不写。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>多于两类型，分离是一条 \\(e(\\theta)\\) 微分方程，混同可以是区间上的池。连续类型下完全混同往往更难精炼掉，也更难完全分离而不耗散。廉价空谈没有单交叉，混同/分离改用 Crawford–Sobel 的区间分割，不在本课。接收者若有市场力，工资不再等于产出，IC 的数字改，两类均衡的定义不改。</p><p>后课默认：谈 PBE 先声明是混同还是分离，并写出路径外信念；精炼后默认最小成本分离，除非题目明确要混同。</p><h3 id="路径外不是可以不写的附录" tabindex="-1">路径外不是可以不写的附录 <a class="header-anchor" href="#路径外不是可以不写的附录" aria-label="Permalink to &quot;路径外不是可以不写的附录&quot;">​</a></h3><p>只写「存在混同均衡」而不写 \\(\\mu(e&#39;)\\)，等于没构造。分离若声称唯一，必须说明用了哪条精炼，否则高 \\(e\\) 的分离也是 PBE。MWG 把这一点写在精炼小节；本课把它当成构造的一部分。</p><p><span class="marginnote">常见误区：把「存在混同均衡」读成「信号一定没信息」。混同说的是路径上没人偏离、后验停在先验；真有人偏离时，路径外信念的写法决定均衡还成不成立。所以读论文时看到混同结论，先翻它指定的 \\(\\mu\\)。</span></p><p><span class="marginnote">半分离：低类型在 \\(e_L\\) 与 \\(e_H\\) 之间随机，高类型纯。路径上 \\(\\mu(e_H)\\) 由贝叶斯钉死，不能任意。它介于两类之间，精炼往往也不留。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分离：不同类型不同信号，路径上后验退化。</li><li>混同：同一信号，路径上后验等于先验，靠路径外信念维持。</li><li>精炼通常删混同与浪费分离，留最小成本分离。</li><li>教育故事已在上节；本课只钉两类 PBE 的构造。</li><li>出处：Spence, <em>QJE</em> 1973；MWG, ch. 13。</li></ul>',13))])}const _=i(d,[["render",m]]);export{P as __pageData,_ as default};
